changeSet.sql:
CREATE OR REPLACE TRIGGER BILLING_EVENT.TRG_SHADOW_ORDER_BEFORE
BEFORE INSERT OR UPDATE ON BILLING_EVENT.SHADOW_ORDER
FOR EACH ROW
DECLARE
    v_username VARCHAR2(128);
BEGIN
    SELECT SYS_CONTEXT('USERENV', 'SESSION_USER')
      INTO v_username
      FROM DUAL;

    IF INSERTING THEN
        :NEW.CREATED_DT := CURRENT_TIMESTAMP;
        :NEW.CREATED_BY := v_username;
    END IF;

    :NEW.UPDATED_DT := CURRENT_TIMESTAMP;
    :NEW.UPDATED_BY := v_username;
END;

CREATE OR REPLACE TRIGGER BILLING_EVENT.TRG_SHADOW_PRODUCT_ORDER_BEFORE
BEFORE INSERT OR UPDATE ON BILLING_EVENT.SHADOW_PRODUCT_ORDER
FOR EACH ROW
DECLARE
    v_username VARCHAR2(128);
BEGIN
    SELECT SYS_CONTEXT('USERENV', 'SESSION_USER')
      INTO v_username
      FROM DUAL;

    IF INSERTING THEN
        :NEW.CREATED_DT := CURRENT_TIMESTAMP;
        :NEW.CREATED_BY := v_username;
    END IF;

    :NEW.UPDATED_DT := CURRENT_TIMESTAMP;
    :NEW.UPDATED_BY := v_username;
END;

CREATE OR REPLACE TRIGGER BILLING_EVENT.TRG_SHADOW_ORDER_AUDIT AFTER INSERT OR UPDATE OR DELETE ON BILLING_EVENT.SHADOW_ORDER FOR EACH ROW DECLARE v_action VARCHAR2(10); v_transaction_id VARCHAR2(100); BEGIN IF INSERTING THEN v_action := 'INSERT'; ELSIF UPDATING THEN v_action := 'UPDATE'; ELSIF DELETING THEN v_action := 'DELETE'; END IF;
v_transaction_id := SYS_GUID();
INSERT INTO BILLING_EVENT.SHADOW_ORDER_AUDIT ( AUDIT_ID, AUDIT_TIMESTAMP, AUDIT_ACTION, AUDIT_TRANSACTION_ID, SHADOW_ORDER_ID, CUSTOMER_ORDER_ID, ACCOUNT_ID, ACCOUNT_NUMBER, SITE_ID, ORDER_TYPE, STATUS, TTL_EXPIRES_AT, CREATED_DT, CREATED_BY, UPDATED_DT, UPDATED_BY ) VALUES ( BILLING_EVENT.SEQ_SHADOW_ORDER_AUDIT_ID.NEXTVAL, SYSTIMESTAMP, v_action, v_transaction_id, COALESCE(:NEW.SHADOW_ORDER_ID, :OLD.SHADOW_ORDER_ID), COALESCE(:NEW.CUSTOMER_ORDER_ID, :OLD.CUSTOMER_ORDER_ID), COALESCE(:NEW.ACCOUNT_ID, :OLD.ACCOUNT_ID), COALESCE(:NEW.ACCOUNT_NUMBER, :OLD.ACCOUNT_NUMBER), COALESCE(:NEW.SITE_ID, :OLD.SITE_ID), COALESCE(:NEW.ORDER_TYPE, :OLD.ORDER_TYPE), COALESCE(:NEW.STATUS, :OLD.STATUS), COALESCE(:NEW.TTL_EXPIRES_AT, :OLD.TTL_EXPIRES_AT), COALESCE(:NEW.CREATED_DT, :OLD.CREATED_DT), COALESCE(:NEW.CREATED_BY, :OLD.CREATED_BY), COALESCE(:NEW.UPDATED_DT, :OLD.UPDATED_DT), COALESCE(:NEW.UPDATED_BY, :OLD.UPDATED_BY) ); END;

