v_transaction_id := SYS_GUID();
INSERT INTO BILLING_EVENT.SHADOW_PRODUCT_ORDER_AUDIT ( AUDIT_ID, AUDIT_TIMESTAMP, AUDIT_ACTION, AUDIT_TRANSACTION_ID, SHADOW_PRODUCT_ORDER_ID, SHADOW_ORDER_ID, PRODUCT_ID, PAID_QUANTITY, FREE_QUANTITY, CHECKED_IN_STATUS, OCCURRENCE_NUMBER, PRODUCT_TYPE, PRODUCT_SEQUENCE, CATEGORY_CODE, CATEGORY_STATUS, CATEGORY_SEQUENCE, CREATED_DT, CREATED_BY, UPDATED_DT, UPDATED_BY ) VALUES ( BILLING_EVENT.SEQ_SHADOW_PROD_ORDER_AUD_ID.NEXTVAL, SYSTIMESTAMP, v_action, v_transaction_id, COALESCE(:NEW.SHADOW_PRODUCT_ORDER_ID, :OLD.SHADOW_PRODUCT_ORDER_ID), COALESCE(:NEW.SHADOW_ORDER_ID, :OLD.SHADOW_ORDER_ID), COALESCE(:NEW.PRODUCT_ID, :OLD.PRODUCT_ID), COALESCE(:NEW.PAID_QUANTITY, :OLD.PAID_QUANTITY), COALESCE(:NEW.FREE_QUANTITY, :OLD.FREE_QUANTITY), COALESCE(:NEW.CHECKED_IN_STATUS, :OLD.CHECKED_IN_STATUS), COALESCE(:NEW.OCCURRENCE_NUMBER, :OLD.OCCURRENCE_NUMBER), COALESCE(:NEW.PRODUCT_TYPE, :OLD.PRODUCT_TYPE), COALESCE(:NEW.PRODUCT_SEQUENCE, :OLD.PRODUCT_SEQUENCE), COALESCE(:NEW.CATEGORY_CODE, :OLD.CATEGORY_CODE), COALESCE(:NEW.CATEGORY_STATUS, :OLD.CATEGORY_STATUS), COALESCE(:NEW.CATEGORY_SEQUENCE, :OLD.CATEGORY_SEQUENCE), COALESCE(:NEW.CREATED_DT, :OLD.CREATED_DT), COALESCE(:NEW.CREATED_BY, :OLD.CREATED_BY), COALESCE(:NEW.UPDATED_DT, :OLD.UPDATED_DT), COALESCE(:NEW.UPDATED_BY, :OLD.UPDATED_BY) ); END;

